rules:
// Example rules. p = current reading, prev = previous one.
// Return rows: [description, expected, read, isOk]
const has=k=>typeof p[k]==='number'&&isFinite(p[k]);
const near=(a,b,pct,abs)=>Math.abs(a-b)<=Math.abs(a)*pct/100+(abs||1);

// Judge the loop only once it has settled, otherwise every transient looks wrong.
const settled=near(p.Temp,prev.Temp,0,0.05);

const rows=[
  ['temperatura trzyma nastawe', p.TempSetpoint, p.Temp, !settled||near(p.TempSetpoint,p.Temp,0,0.5)],
  ['zawor w dozwolonym zakresie', p.ValveMax, p.Valve, p.Valve>=p.ValveMin&&p.Valve<=p.ValveMax],
];
const missing=['TempSetpoint','Temp','Valve'].filter(k=>!has(k));
if(missing.length)
  rows.push(['BRAK PUNKTOW (sprawdz mapowanie): '+missing.join(', '), 0, missing.length, false]);
return rows;
